/**
 * 宣言済みパスの `prev` 台帳へ旧値を記録する。台帳を読むのは `$watch`
 * （docs/state-watch-hook-design.md §4-1）と `$scan` の `from`（docs/state-scan-design.md §2-1）。
 *
 * same-value guard が既に読んだ旧値だけを使い、そのための追加読みはしない。
 * 台帳の実体は watch/addressHooks.ts の writeObserve hook（`$watch` / `$scan` を宣言した state にだけ付く）。
 * 宣言の無い state は `addressHooks` の null 判定 1 個で抜ける。
 */
function recordDeclaredPrevValue(
  stateElement: IStateHandler["stateElement"],
  path: string,
  absAddress: IAbsoluteStateAddress,
  oldValue: unknown,
  hasOldValue: boolean,
): void {
  const hooks = stateElement.addressHooks;
  if (hooks) {
    const observers = hooks.writeObserve;
    for (let i = 0; i < observers.length; i++) {
      observers[i](stateElement, path, absAddress, oldValue, hasOldValue);
    }
  }
}

// 書き込み・入れ替えの後の通知（設計案 H1 の written / swapped）: 観測面を持つ機能（DCC の
// bindable イベント・watch の旧値台帳）が state に付けた hook だけを呼ぶ
function notifyWritten(stateElement: IStateHandler["stateElement"], pathInfo: IStateAddress["pathInfo"], detail?: { readonly value: unknown }): void {
  const hooks = stateElement.addressHooks;
  if (hooks) {
    const written = hooks.written;
    for (let i = 0; i < written.length; i++) {
      written[i](stateElement, pathInfo, detail);
    }
  }
}

function notifySwapped(stateElement: IStateHandler["stateElement"], elementAbsAddress: IAbsoluteStateAddress, displacedAbsAddress: IAbsoluteStateAddress): void {
  const hooks = stateElement.addressHooks;
  if (hooks) {
    const swapped = hooks.swapped;
    for (let i = 0; i < swapped.length; i++) {
      swapped[i](stateElement, elementAbsAddress, displacedAbsAddress);
    }
  }
}

// Phase 3: 書き込み時点の因果 context を update record に付与する。
// binding 経由の書き込みは呼び出し元の dynamic scope から context を引き継ぎ、
// binding 外からの API update は新しい transaction を開始する（設計書 §4 規則 1）。
// 依存 walk で enqueue される派生アドレスも同じ書き込みの因果に属する。

// 鍵付き購読（`$eq` 系、dependency/keyedDependency.ts）への通知。同値ガードが読んだ旧値と
// 新値の鍵に登録された行だけを dirty 化して enqueue する。購読の無いパスは Map 参照 2 回で抜ける。
// 祖先への書き込み（`$eq("sel.id")` に対する `sel = {…}`）は配下の鍵付きパスへ知らせる。その旧値は
// 同値ガードが読めなかったときだけ `readOld` で書き込み前に読む
function notifyKeyed(
  stateElement: IStateHandler["stateElement"],
  path: string,
  hasOldValue: boolean,
  oldValue: unknown,
  value: unknown,
  readOld: () => unknown,
): IAbsoluteStateAddress[] | null {
  const direct = hasKeyedDependents(stateElement, path);
  const descendants = hasKeyedDescendants(stateElement, path);
  if (!direct && !descendants) {
    return null;
  }
  const subscribers: IAbsoluteStateAddress[] = [];
  const enqueue = createKeyedEnqueue(subscribers);
  if (direct) {
    keyedDependents(stateElement, path, hasOldValue, oldValue, value).forEach(enqueue);
  }
  if (descendants) {
    keyedDescendantDependents(stateElement, path, hasOldValue ? oldValue : readOld(), value).forEach(enqueue);
  }
  return subscribers;
}

/** 鍵付き通知の伝播 context（`createKeyedEnqueue` と `walkKeyedDependents` で 1 本にする） */
function keyedPropagationContext(): ReturnType<typeof getCurrentPropagationContext> | null {
  return config.enablePropagationContext ? (getCurrentPropagationContext() ?? null) : null;
}

/** 集めた購読者を `collected` へ控える（依存ウォークの起点。`walkKeyedDependents` が書き込み後に使う） */
function createKeyedEnqueue(collected: IAbsoluteStateAddress[]): (absAddress: IAbsoluteStateAddress) => void {
  const updater = getUpdater();
  const context = keyedPropagationContext();
  return (absAddress: IAbsoluteStateAddress): void => {
    dirtyCacheEntryByAbsoluteStateAddress(absAddress);
    updater.enqueueAbsoluteAddress(absAddress, context);
    collected.push(absAddress);
  };
}

/**
 * 鍵付き購読の購読者から、その**依存先**へ通知を伝播する。
 *
 * 鍵付き購読（`$eq` 系）は意図的に依存グラフに載らない（載せると選択の更新が全行に広がる）。
 * その代わり `notifyKeyed` が購読者のアドレスを直に enqueue するのだが、**そこで止まっていた**ため
 * 「鍵付き getter に依存する別の getter / バインディング」が陳腐化していた（素のツリーで再現。
 * docs/state-keyed-derived-propagation.md）。通常の書き込みは `notifyWrite` が同じ enqueue の後に
 * `walkDependency` を回しており、鍵付きだけが非対称だった。
 *
 * **収集は書き込みの前・ウォークはこの関数で書き込みの後**に分ける。`notifyKeyed` が
 * `Reflect.set` より前に走るのは旧値の鍵で「前に選ばれていた行」を引くためで、一方
 * `walkDependency` はリスト展開で書き込み**後**の値を読む前提（`notifyWrite` が `finally` に
 * いるのと同じ理由）。前で walk すると書き込み前の配列で展開してしまう。
 *
 * ホットパス（R2）: 鍵付き選択の存在理由は「選択の更新を 2 行に抑える」ことなので、購読者ごとに
 * 依存表を 2 回引くだけの短絡を先に置く。依存先を持つ購読者は稀で、持たなければ
 * `createStateAddress` の割り当ても `walkDependency` の呼び出しも起きない。
 */
function walkKeyedDependents(
  subscribers: IAbsoluteStateAddress[] | null,
  receiver: any,
  handler: IStateHandler,
): void {
  if (subscribers === null || subscribers.length === 0) {
    return;
  }
  const stateElement = handler.stateElement;
  const staticDependency = stateElement.staticDependency;
  const dynamicDependency = stateElement.dynamicDependency;
  const updater = getUpdater();
  const context = keyedPropagationContext();
  for (let i = 0; i < subscribers.length; i++) {
    const treePath = subscribers[i].absolutePathInfo;
    const path = treePath.pathInfo.path;
    // 依存先ゼロの購読者（大多数）は Map 参照 2 回で抜ける
    if (!staticDependency.has(path) && !dynamicDependency.has(path)) {
      continue;
    }
    const address = createStateAddress(treePath.pathInfo, subscribers[i].listIndex);
    walkDependency(
      stateElement,
      address,
      staticDependency,
      dynamicDependency,
      stateElement.listPaths,
      receiver as IStateProxy,
      "new",
      (depAddress: IStateAddress) => {
        // 起点（購読者自身）は createKeyedEnqueue が済ませている — 二重 enqueue を避ける
        if (depAddress === address) return;
        const absDepAddress = liftAddress(stateElement, depAddress);
        dirtyCacheEntryByAbsoluteStateAddress(absDepAddress);
        updater.enqueueAbsoluteAddress(absDepAddress, context);
      },
      // `notifyWrite` と同じ規準。購読者は普通リストではないので実質効かないが、
      // 万一リストでも未変更行まで展開しない
      { listExpansion: "diff" },
    );
  }
}

/**
 * `$postUpdate` の鍵付き通知（proxy/apis/postUpdate.ts）。
 *
 * in-place 変異を通知する正規の idiom なので、呼ばれた時点で**変異はもう起きている** —
 * `setByAddress` と違って旧値がどこにも無い。`hasOldKey = false` で引くと、台帳が控えている
 * 「最後に観測した鍵」（`lastValue`）が旧値の代わりになり、前に選ばれていた行も
 * 新しく選ばれる行も一緒に再評価される。これが無いと `raw.sel.id = 2; $postUpdate("sel.id")` で
 * 前の行が真のまま残った（2.6.0 で `setByAddress` 側に入れた修正の取りこぼし）。
 *
 * 現在値の読みは購読があるときだけ行う（`readCurrent` の thunk）。
 */
export function notifyKeyedPostUpdate(
  stateElement: IStateHandler["stateElement"],
  path: string,
  readCurrent: () => unknown,
  receiver: any,
  handler: IStateHandler,
): void {
  const direct = hasKeyedDependents(stateElement, path);
  const descendants = hasKeyedDescendants(stateElement, path);
  if (!direct && !descendants) {
    return;
  }
  const current = readCurrent();
  const subscribers: IAbsoluteStateAddress[] = [];
  const enqueue = createKeyedEnqueue(subscribers);
  if (direct) {
    keyedDependents(stateElement, path, false, undefined, current).forEach(enqueue);
  }
  if (descendants) {
    keyedDescendantDependents(stateElement, path, undefined, current, false).forEach(enqueue);
  }
  // `$postUpdate` は変異が**もう起きた**後に呼ばれるので、収集とウォークを分ける必要がない
  // （`setByAddress` 側だけが `Reflect.set` を跨ぐ）。派生先へ届かない穴は両方にあった
  walkKeyedDependents(subscribers, receiver, handler);
}

function notifyWrite(
  address  : IStateAddress,
  absAddress: IAbsoluteStateAddress,
  receiver : any,
  handler  : IStateHandler,
  keyedMergePath: string | null,
  cacheable: boolean,
  listExpansion: "diff" | "full" = "diff"
): void {
  const propagationContext = config.enablePropagationContext
    ? (getCurrentPropagationContext() ?? beginPropagationTransaction(-1))
    : null;
  const updater = getUpdater();
  const stateElement = handler.stateElement;
  updater.enqueueAbsoluteAddress(absAddress, propagationContext);
  // 書いたアドレス自身のキャッシュを、依存ウォークより先に無効化する（#274）。ウォークはリスト展開
  // （list → list.*）と動的依存の親リスト展開で、書いたパスの値を読む。ワイルドカードを含むリストパス
  // （`groups.*.items`）はキャッシュ対象なので、無効化しないと書き込み前の配列がヒットし、基準との差分が
  // 「変化なし」になって置き換える前の行だけを展開する（長い配列に置き換えた分の行が着地しない）。
  // 依存先は下の callback が訪問のたびに読む前に無効化するが、開始アドレスは callback が飛ばす
  // （二重 enqueue の防止）のでここで済ませる — 開始アドレスも callback で無効化する $postUpdate と同じ順序。
  // 値は直後の commitWriteCache が載せ直す。
  if (cacheable) {
    dirtyCacheEntryByAbsoluteStateAddress(absAddress);
  }
  // 依存関係のあるキャッシュを無効化（ダーティ）、更新対象として登録
  const walk = (start: IStateAddress): IStateAddress[] => walkDependency(
    stateElement,
    start,
    stateElement.staticDependency,
    stateElement.dynamicDependency,
    stateElement.listPaths,
    receiver as IStateProxy,
    "new",
    (depAddress: IStateAddress) => {
      // キャッシュを無効化（ダーティ）
      if (depAddress === address) return;
      const absDepAddress = liftAddress(stateElement, depAddress);
      dirtyCacheEntryByAbsoluteStateAddress(absDepAddress);
      // 更新対象として登録
      updater.enqueueAbsoluteAddress(absDepAddress, propagationContext);
    },
    // リスト置換時は追加行・位置変更行のみ展開する（未変更行の再訪を省く。
    // $postUpdate の手動リフレッシュは従来通り全行展開のまま）
    { listExpansion, keyedMergePath }
  );
  walk(address);
  // 入れ子のリストの行の下への書き込みは、同じ要素オブジェクトを表す別の配列の行（共有された配列の写し）のアドレスにも知らせる
  // （#393）。描画だけをやり直させる — 着地はこの書き込みのアドレス 1 つで、依存ウォークもしない（同じバッチの差分が
  // 途中の配列に作った行も同じ要素を表すので、そこからリストを展開すると台帳の行の親をその行へ付け替えてしまう）
  if (address.pathInfo.lastSegment !== WILDCARD && address.listIndex !== null && address.listIndex.parentListIndex !== null) {
    const row = address.listIndex;
    const listPathInfo = address.pathInfo.wildcardParentPathInfos[row.position];
    const listAddress = createStateAddress(listPathInfo, row.parentListIndex);
    const readList = () => receiver[getByAddressSymbol](listAddress);
    const notify = (aliasAbsAddress: IAbsoluteStateAddress) => {
      dirtyCacheEntryByAbsoluteStateAddress(aliasAbsAddress);
      updater.enqueueRenderOnlyAddress(aliasAbsAddress);
    };
    for (const alias of getElementAliases(row, readList)) {
      notify(liftAddress(stateElement, createStateAddress(address.pathInfo, alias)));
    }
    // 同じ配列を別のパスの `for` も描いている（`{ items: A, alt: A }` の `alt`）なら、その `for` の同じ行の同じ葉にも知らせる
    // （描画の基準の逆引き — 描画だけ）。葉の書き込みの依存はパスごとなので、`alt` の `for` は描き直されなかった
    const leaf = address.pathInfo.path.slice(address.pathInfo.wildcardPaths[row.position].length);
    for (const drawn of getAddressesByLastListValue(liftAddress(stateElement, listAddress), readList())) {
      const drawnPathInfo = drawn.absolutePathInfo.pathInfo;
      if (drawnPathInfo !== listPathInfo && drawnPathInfo.wildcardCount === listPathInfo.wildcardCount) {
        notify(absoluteAddressOf(stateElement, getPathInfo(drawnPathInfo.path + DELIMITER + WILDCARD + leaf), row));
      }
    }
  }
  // 書いた行のリストを、別のパスの `for` が同じ配列として描いている（配列をそのまま返す getter —
  // TodoMVC の `get shown() { return this.filter === "all" ? this.todos : … }`）なら、そのパスの同じ行へも
  // 知らせる（#362）。行の台帳は配列ごとに 1 組なので 2 つのパスの行は同じ listIndex だが、キャッシュ・依存・
  // 束縛はパスごとで、`todos.*.done` の依存ウォークは `shown.*.done` に届かず、行は次にリストを描くまで
  // 古いままだった。候補は、書いたパスの各段のリストを読んだ getter のうち、`for` で描き、読んだパスの値を
  // そのまま返したことのあるもの（getByAddress の isAliasGetter）— 段ごとに依存の表を 1 回引くだけで、別名の
  // 無いページ（写しだけを返す getter のページを含む）の書き込みには値の読みを足さない。行の深さが同じ（getter の
  // ワイルドカードの数がその段と同じ）で、いまも値が同じ配列のときだけ別名とする。要素の書き込みは行が新しくなる
  // （renewReplacedRow・入れ替え）ので、別名の `for` も描き直させる
  const { path, lastSegment, wildcardCount, wildcardParentPaths, wildcardParentPathInfos } = address.pathInfo;
  const listIndex = address.listIndex;
  for (let level = 0; listIndex && level < wildcardCount; level++) {
    const parentListIndex = listIndexAtWildcard(listIndex, level - 1, wildcardCount);
    for (const aliasPath of stateElement.dynamicDependency.get(wildcardParentPaths[level]) ?? []) {
      const aliasPathInfo = getPathInfo(aliasPath);
      if (stateElement.listPaths.has(aliasPath) && aliasPathInfo.wildcardCount === level && isAliasGetter(aliasPathInfo) &&
        receiver[getByAddressSymbol](createStateAddress(aliasPathInfo, parentListIndex)) ===
          receiver[getByAddressSymbol](createStateAddress(wildcardParentPathInfos[level], parentListIndex))) {
        const aliasAddress = createStateAddress(getPathInfo(aliasPath + path.slice(wildcardParentPaths[level].length)), listIndex);
        walk(aliasAddress);
        if (lastSegment === WILDCARD) {
          updater.enqueueRenderOnlyAddress(liftAddress(stateElement, aliasAddress.parentAddress!));
        }
      }
    }
  }
}

/**
 * 書き込み完了後のキャッシュ整合（Issue #234）。
 *
 * ワイルドカードのデータパス（リスト行）は代入値がそのまま格納値なので、
 * 代入値を dirty:false で載せて次回の読みを省く。
 *
 * アクセサペア（getterPaths に載るパス）は getter が正本であり、setter は
 * 命令的な代入に過ぎない。代入値を getter の評価結果として固定すると
 * - setter が正規化・分配した結果と読みが食い違う
 * - getter が一度も評価されず動的依存が張られない → 依存先を書いても
 *   walkDependency がこのキャッシュを dirty にできず、永続的に stale になる
 *   （プリミティブ代入は同値ガードの旧値読みで偶然 getter が走るが、
 *   オブジェクト代入は同値ガードを素通りするため救済がない）
 * ため、キャッシュを dirty にして次回の読みで getter を再評価させる。
 */
function commitWriteCache(
  stateElement: IStateHandler["stateElement"],
  path: string,
  absAddress: IAbsoluteStateAddress,
  value: unknown,
  cacheable: boolean,
): void {
  if (!cacheable) {
    return;
  }
  if (stateElement.getterPaths.has(path)) {
    dirtyCacheEntryByAbsoluteStateAddress(absAddress);
    return;
  }
  setCacheEntryByAbsoluteStateAddress(absAddress, {
    value: value,
    dirty: false,
    // 読み側（getByAddress）と同じ世代印・行の印を付ける — ヒットになるのは両方が一致する項目だけ
    // （cache/types.ts の `generation` / `rowStamp`）。行の印は書き込みの依存ウォークが進めた後の値
    generation: stateElement.stateGeneration,
    rowStamp: absAddress.absolutePathInfo.pathInfo.lastSegment === WILDCARD ? undefined : getRowCacheStamp(absAddress.listIndex)
  });
}

/**
 * 要素の書き込み（`items.0 = {…}`）でその位置の要素が別の値に替わるなら、その位置を新しい行にし、
 * 新しい行のアドレスを返す（#333）。`for` が描くリストの入れ替えの経路（`_setByAddressWithSwap`）と
 * 同じ同一性モデル — 行は要素に付き、別の要素は別の行。
 *
 * 行の下のパス（`items.*.name`・行 getter）はワイルドカードを含むので行の listIndex ごとに
 * キャッシュされる（isCacheable）。行を据え置くと、行から子へ静的な辺の無い（`for` で描いていない）
 * リストでは、依存ウォークが子に届かず古い値が返り続けた。新しい行には子のキャッシュが無いので、
 * どう読まれても（直接添字・`$getAll`・getter）書いた要素から読み直す。差し替えた行は退役させる —
 * `$watch` / `$scan` の着地はその行を捨てて新しい行で受け（rowLanding.ts）、要素と一緒に持ち越された
 * 入れ子のリストの行集合は、次の解決で新しい行へ付け替わる（#256）。
 * 要素パス自身の `$watch` の prev は、同じバッチでその位置の前の行が記録した値を引き継ぐ（入れ替えの
 * 経路の notifySwapped と同じ。引き継がないと、同じ位置を 2 回書いたとき 1 回目の値が prev になる）。
 * 同じ要素の書き込み（通知だけの再代入）は行を据え置く。台帳のその位置がこのアドレスの行でなければ
 * （台帳が無い・listIndex の無いアドレス）何もしない。
 */
function renewReplacedRow(
  stateElement: IStateHandler["stateElement"],
  address: IStateAddress,
  list: any,
  key: PropertyKey | undefined,
  value: unknown,
): IStateAddress {
  const row = address.listIndex!;
  const listIndexes = getListIndexesByList(list);
  if (listIndexes?.[key as number] !== row || list[key as number] === value) {
    return address;
  }
  const renewed = createListIndex(row.parentListIndex, key as number, getHomeParentListIndex(row));
  // この配列を描いた `for` が描いたのは書き込む前の行。書き込む前の並びの写しに前の台帳を持たせ、描画の
  // 基準をそこへ移す（入れ替えの経路の notifySwappedList と同じ）。別のパスの `for`（配列をそのまま返す
  // getter・同じ配列を持つ別のキーや state）は台帳の差し替えを知らず、描いていない新しい行を描いたつもりで
  // 差分を取っていた。移すのは描いた後の最初の書き込みだけ。同じ配列の入れ替え（別のキーの `for` が描く）の
  // 途中なら、描いたのは入れ替えの前の並び — 配列もその途中の姿なので、入れ替えが控えた写しを使う
  if (hasRenderedList(list)) {
    const image = getSwapInfoByList(list) ?? { value: list.slice(), listIndexes: listIndexes! };
    setListIndexesByList(image.value, image.listIndexes);
    rebaseRenderedList(list, image.value);
  }
  // 台帳の配列を持つ別の持ち手（差分のキャッシュ・別の配列の台帳・上の写し・入れ替え・`$eqIndex` の監視）が
  // いれば、写してから差し替える — その場で書き換えると持ち手の行まで書き換わる（#335）。前の書き込みが
  // 写したまま誰も持っていない台帳は、その場で書き換える（listIndexesByList.ts の isOwnedListIndexes）。
  // `$eqIndex` の監視は台帳の配列に付くので一緒に移す（移した先は監視が持つので、所有を外す）
  const next = isOwnedListIndexes(listIndexes!) ? listIndexes! : listIndexes!.slice();
  next[key as number] = renewed;
  setListIndexesByList(list, next, true);
  moveIndexWatchers(listIndexes!, next);
  retireRows([row]);
  const renewedAddress = createStateAddress(address.pathInfo, renewed);
  notifySwapped(stateElement, liftAddress(stateElement, renewedAddress), liftAddress(stateElement, address));
  return renewedAddress;
}

function _setByAddress(
  target   : object,
  address  : IStateAddress,
  absAddress: IAbsoluteStateAddress,
  value    : any,
  receiver : any,
  handler  : IStateHandler,
  keyedMergePath: string | null,
  cacheable: boolean,
  // false なら書き込みだけ（入れ替えの経路は、どの行に着地させるかを書いた後で決める — _setByAddressWithSwap）
  notify = true,
): any {
  try {
    if (address.pathInfo.path in target) {
      if (handler.stateElement.setterPaths.has(address.pathInfo.path)) {
        // setterの中で参照の可能性があるので、addressをプッシュする。
        // setter は命令的な代入であって派生（getter）ではないため、実行中の
        // 読み取り（同値ガードの旧値読み・$1 参照等）で依存を張らない。
        // アクセサペア（get/set 同名パス）では、抑止しないと setter 内の内部
        // 書き込みの同値ガード読みが「getter の依存」として誤登録される。
        handler.pushAddress(address);
        handler.beginUntrack();
        try {
          return Reflect.set(target, address.pathInfo.path, value, receiver);
        } finally {
          handler.endUntrack();
          handler.popAddress();
        }

      } else {
        return Reflect.set(target, address.pathInfo.path, value);
      }
    } else {
      const parentAddress = address.parentAddress;
      if (parentAddress === null) {
        return Reflect.set(target, address.pathInfo.path, value);
      }
      const parentValue = getByAddress(target, parentAddress, receiver, handler);
      const lastSegment = address.pathInfo.segments[address.pathInfo.segments.length - 1];
      if (lastSegment === WILDCARD) {
        // 読み取り側（getByAddress）と同じ取り違え。書き込みでも何段必要かを言う。
        const index = address.listIndex?.index ?? raiseError(
          wildcardScopeMessage(
            `path "${address.pathInfo.path}"`,
            address.pathInfo.wildcardCount,
            address.listIndex?.length ?? 0,
          ),
        );
        return Reflect.set(parentValue, index, value);
      } else {
        // 公開 getter への書き込み（X9）は setByAddressCore の fast path（親がオブジェクトの
        // 未存在キー）で dispatch 済み。ここに来るのは親が非オブジェクトの形だけ
        return Reflect.set(parentValue, lastSegment, value);
      }
    }
  } finally {
    if (notify) {
      notifyWrite(address, absAddress, receiver, handler, keyedMergePath, cacheable);
    }
  }
}

function _setByAddressWithSwap(
  target   : object,
  address  : IStateAddress,
  absAddress: IAbsoluteStateAddress,
  value    : any,
  receiver : any,
  handler  : IStateHandler,
  keyedMergePath: string | null,
  cacheable: boolean,
  elementWrite: number
) {
  // elementsの場合はswapInfoを準備（キーはリストの配列そのもの — swapInfo.ts 参照）
  const parentAddress = address.parentAddress ?? raiseError(`address.parentAddress is undefined path: ${address.pathInfo.path}`);
  const parentValue = getByAddress(target, parentAddress, receiver, handler) ?? [];
  const swapInfo = getSwapInfoByList(parentValue);
  if (elementWrite) {
    // 要素から来た書き込み（行の要素が自分の行へ出す値）は、その行の値の更新で入れ替えではない
    // （proxy/occurrenceWrite.ts・#337）。行はそのまま、途中の入れ替えがあればその写しでもこの行の値にして、
    // 揃ったかの突き合わせがこの行を動かさないようにする
    if (swapInfo) {
      swapInfo.value[address.listIndex!.index] = value;
    }
    // 行はこの位置のまま書いた要素を映す。同じ行を持つ前の配列へ戻したとき、差分がこの行を描き直させる（#359）
    setListIndexValue(address.listIndex!, value);
    return _setByAddress(target, address, absAddress, value, receiver, handler, keyedMergePath, cacheable);
  }
  const row = address.listIndex!;
  // 書き込む前の並び。台帳の配列は書き換えないので写さない（下の matchSwappedListIndexes）
  const info = swapInfo ?? {
    value: [...parentValue], listIndexes: getListIndexesByList(parentValue) ?? [], written: new Map(),
  };
  try {
    // 通知は下で、入れ替えが揃ったかを見てから（揃うと行が動くので、着地させる行が変わる — #361）
    return _setByAddress(target, address, absAddress, value, receiver, handler, keyedMergePath, cacheable, false);
  } finally {
    const currentListIndexes = matchSwappedListIndexes(info, parentValue, parentAddress.listIndex);
    if (currentListIndexes === null) {
      setSwapInfoByList(parentValue, info);
      // 揃うまで行はこの位置のまま書いた要素を映す（#359 — 上の要素から来た書き込みと同じ）。この書き込みは
      // この行に着地する
      setListIndexValue(row, value);
      info.written.set(row, updateBatch);
      markRowSwapPending(row);
      notifyWrite(address, absAddress, receiver, handler, keyedMergePath, cacheable);
    } else {
      // 揃ったので swapInfo を削除し、台帳を新しい配列に差し替える。その場で書き換えると、同じ配列を
      // 持つ差分のキャッシュ（置き換えの差分の newIndexes）や、同じ中身の配列の台帳（createListDiff の
      // isSameList）まで書き換わり、`for` が描いていない行を描いたつもりで差分を取る（#335）
      setSwapInfoByList(parentValue, null);
      // このバッチで書いた位置 — この書き込みと、揃う前の書き込みの位置（行の index を振り直す前に控える・#361）。
      // 揃う前の書き込みで書いた値を映していた行は、自分の要素（書き込む前のその位置の要素）に戻す（#359。
      // 押し出された行に書いた値を残すと、着地の選別がその値の行と取り違える）
      const positions = [row.index];
      clearRowSwapPending(row);
      info.written.forEach((batch, written) => {
        clearRowSwapPending(written);
        setListIndexValue(written, info.value[written.index]);
        if (batch === updateBatch) {
          positions.push(written.index);
        }
      });
      // この書き込みの行はまだ着地していない — 揃う前に同じ行へ書いていても、その後の読み（同値ガード）が前の値を
      // キャッシュに載せ直しているので、書いた位置に残るなら通知し直す（notifySwappedList）
      info.written.delete(row);
      currentListIndexes.forEach((listIndex, i) => {
        listIndex.index = i;
      });
      setListIndexesByList(parentValue, currentListIndexes);
      // `$eqIndex` の監視は台帳の配列に付く（差分が付け替えるのと同じ）
      moveIndexWatchers(info.listIndexes, currentListIndexes);
      notifySwappedList(parentAddress, info, parentValue, currentListIndexes, receiver, handler, positions);
    }
  }
}

/**
 * 要素書き込みの入れ替えが揃ったかを見て、揃っていればいまの並びの台帳を返す（#4・#337）。
 *
 * 行は値に付いて動く: 値の変わらない位置はその行のまま、値の変わった位置には、その値を書き込む前に
 * 持っていて今は別の値になった行（動いてきた行）を充て、無ければ新しい行を作る。
 * 書き込む前の並びにあった値が、動いてきた行より多くの位置に現れているうちは入れ替えの途中（片側だけを
 * 書いた — 値がまだ元の位置にも残っている）で、null を返す。その間、台帳は書き込む前の行のままなので、
 * 位置の読み書きはその行の index で当たり、表示も位置どおりに正しい。
 * 揃った印は値が重複しないことではない（#337）。同じ値の行を含む並びの入れ替えも揃い、別の行と同じ値を
 * 書いて同じ値の行が増えた並び（入れ替えの片側と区別できない）は、揃わないまま位置どおりに描かれる。
 * 位置は台帳の行の分だけ見る（行の無い位置は書き込みの宛先にならない）。
 * 手間は 1 回の書き込みにつき O(n)（`$setAll` は n 回書く）。動いてきた行の無い値が書き込む前の並びに
 * あるかは、1 つ目は `includes`、2 つ目からは Set で引く（1 つずつ引くと、新しい値を多く書いた並びで
 * O(k·n) になる）。新しい行は、揃ったと決まってから作る。行の index の振り直しは呼び手がする（振り直す前の
 * 位置で、このバッチに書いた位置を控えるため）。
 */
function matchSwappedListIndexes(swapInfo: ISwapInfo, list: unknown[], parentListIndex: IListIndex | null): IListIndex[] | null {
  const { value: before, listIndexes: rows } = swapInfo;
  const movedByValue = new Map<unknown, IListIndex[]>();
  rows.forEach((row, i) => {
    if (list[i] !== before[i]) {
      const moved = movedByValue.get(before[i]);
      if (moved) {
        moved.push(row);
      } else {
        movedByValue.set(before[i], [row]);
      }
    }
  });
  let lookups = 0;
  let beforeValues: Set<unknown> | undefined;
  const listIndexes: (IListIndex | undefined)[] = [];
  for (let i = 0; i < rows.length; i++) {
    const listIndex = list[i] === before[i] ? rows[i] : movedByValue.get(list[i])?.shift();
    if (!listIndex && (lookups++ ? (beforeValues ??= new Set(before)).has(list[i]) : before.includes(list[i]))) {
      return null;
    }
    listIndexes.push(listIndex);
  }
  return listIndexes.map((listIndex, i) => listIndex ?? createListIndex(parentListIndex, i));
}

/**
 * 要素書き込みの入れ替え（または行の置き換え）が揃ったとき、リストを「書き込む前の並び →
 * いまの並び」の置換として描画し直させる（#4 — 同一性モデル）。
 *
 * 台帳は上で「listIndex は値に付いて動く」形に組み替え済み。ところが `for` の描画基準
 * （lastListValue）はその場で書き換えられた同じ配列なので、差分に入れ替えが映らず、ブロックは
 * 動かないまま中身だけが書き換わっていた。基準を「書き込む前の並びの写し」とその台帳の写しに
 * すると、`for` は写しといまの配列の差分を listIndex の同一性で突き合わせ（createListDiff の
 * calcDiffIndexes）、ブロックを値と一緒に動かし、置き換えた行を作り直す。基準を写しに替えるのは、
 * 描画基準がいま入れ替えている配列そのもののときだけ — 同じバッチで配列を丸ごと書き換えた後なら、
 * 描画はまだその前の配列で、そちらとの差分が入れ替えも含む。
 *
 * 行ごとの扱い（書き込む前といまの台帳の位置を比べる）:
 *  - 位置が変わらない行: 何もしない。
 *  - 新しい listIndex の行（書き込む前の台帳に無い）: その位置の値の書き込みとして着地させる。差し替えられた
 *    行は `for` の差分で退役し、その行のアドレスの着地は `$watch` / `$scan` の選別で捨てられるので、
 *    着地は新しい行が持つ（#274 の「その位置のいまの値で 1 回」）。要素パス自身の prev は、書き込みがその位置の
 *    前の行のアドレスで記録した値を引き継ぐ（引き継がないと `$watch "items.*"` の prev が消える）。ブロックは
 *    `for` が同じ位置で外す行の Content をその場で使い回す（applyChangeToFor の collectInPlaceContents）。
 *  - 値と一緒に動いた行: 値は変わっていないので、依存を無効化して描画だけをやり直す。書き込みを別の
 *    バッチに分けると、途中のバッチで別の値を描いた行が残る。
 * 書き込みの着地は書いた位置（#361）。このバッチで書いた位置（`positions` — 揃えた書き込みと、揃う前の書き込み）
 * にいま居る行のうち、このバッチでまだ着地していない行（書いた行のままの位置・動いてきた行）を、その位置の値の
 * 書き込みとして着地させる。prev は、その位置の書き込みが書いた行のアドレスで記録した値を引き継ぐ。揃う前の
 * 書き込みはその時点で位置に居た行に着地しており、揃うとその行は値に付いて動く — 同じバッチの書き込みだけで
 * 揃う入れ替えなら動いた先もこのバッチで書いた位置なので、その着地がそのまま当たる。前のバッチの書き込みと揃う
 * と、揃えた書き込みの行は前のバッチで書いた位置へ動く — そこはこのバッチでは変わっていないので着地させない。
 * リスト自身も描画だけを積む（updater の enqueueRenderOnlyAddress）。書き込みとして積むと、`items` の
 * `$watch` が配列の参照の変わらない入れ替えで発火する。
 */

function notifySwappedList(
  parentAddress: IStateAddress,
  swapInfo: ISwapInfo,
  currentParentValue: unknown,
  currentListIndexes: readonly IListIndex[],
  receiver: any,
  handler: IStateHandler,
  positions: readonly number[],
): void {
  const stateElement = handler.stateElement;
  const updater = getUpdater();
  const listAbsAddress = liftAddress(stateElement, parentAddress);
  setListIndexesByList(swapInfo.value, swapInfo.listIndexes);
  markSwapBaselineList(swapInfo.value);
  // この配列を描いた `for` が描いたのは書き込む前の並び。画面から外れていて今回は描かない `for` も、
  // 次に描くときは写しとの差分を取る（#320。下の記録は、今回描く `for` のためのもの）
  rebaseRenderedList(currentParentValue as readonly unknown[], swapInfo.value);
  if (getLastListValueByAbsoluteStateAddress(listAbsAddress) === currentParentValue) {
    setLastListValueByAbsoluteStateAddress(listAbsAddress, swapInfo.value);
  }
  updater.enqueueRenderOnlyAddress(listAbsAddress);
  // この配列を描いている `for` は、書いたリストのアドレスのものだけとは限らない — 同じ内側の配列を別の外側の行も
  // 持つ・同じ行の別のパスも持つ（#379。行の台帳は配列ごとに 1 組なので、同じ行を描いている）。その `for` にも
  // 知らせて描き直させる（描くときにまだこの配列なら、自分が描いた並び — 上で写しへ移した記録 — からの差分を取る）
  for (const absAddress of getAddressesByLastListValue(listAbsAddress, currentParentValue as readonly unknown[])) {
    if (markSwappedList(absAddress, currentParentValue as readonly unknown[])) {
      updater.enqueueRenderOnlyAddress(absAddress);
    }
  }

  const positionBefore = new Map<IListIndex, number>();
  swapInfo.listIndexes.forEach((listIndex, position) => positionBefore.set(listIndex, position));
  const elementPathInfo = getPathInfo(parentAddress.pathInfo.path + DELIMITER + WILDCARD);
  for (let position = 0; position < currentListIndexes.length; position++) {
    const listIndex = currentListIndexes[position];
    const before = positionBefore.get(listIndex);
    if (before === position) {
      continue;
    }
    const elementAddress = createStateAddress(elementPathInfo, listIndex);
    const elementAbsAddress = liftAddress(stateElement, elementAddress);
    if (typeof before === "undefined") {
      // 台帳は書き込む前の台帳と同じ長さで作る（matchSwappedListIndexes）
      const displacedAbsAddress = absoluteAddressOf(stateElement, elementPathInfo, swapInfo.listIndexes[position]);
      notifySwapped(stateElement, elementAbsAddress, displacedAbsAddress);
      // 置き換えで入った行は中身が丸ごと新しい。差分展開だと入れ子のリストの行（`items.*.tags.*`）が
      // 着地せず `$watch` / `$scan` が取り逃すので、この行の下だけ全行展開で通知する
      notifyWrite(
        elementAddress, elementAbsAddress, receiver, handler, null,
        isCacheable(stateElement, elementAddress), "full",
      );
      continue;
    }
    walkDependency(
      stateElement,
      elementAddress,
      stateElement.staticDependency,
      stateElement.dynamicDependency,
      stateElement.listPaths,
      receiver as IStateProxy,
      "new",
      (depAddress: IStateAddress) => {
        const depAbsAddress = liftAddress(stateElement, depAddress);
        dirtyCacheEntryByAbsoluteStateAddress(depAbsAddress);
        updater.enqueueRenderOnlyAddress(depAbsAddress);
      },
      { listExpansion: "diff" },
    );
  }
  // このバッチで書いた位置にいま居る、まだ着地していない行を着地させる（上の説明 — 新しい行は上で着地済み）。
  // 台帳に行の無い位置（台帳の無い配列への書き込み）には居ない
  for (const position of positions) {
    const listIndex = currentListIndexes[position];
    if (positionBefore.has(listIndex) && swapInfo.written.get(listIndex) !== updateBatch) {
      const elementAddress = createStateAddress(elementPathInfo, listIndex);
      const elementAbsAddress = liftAddress(stateElement, elementAddress);
      notifySwapped(stateElement, elementAbsAddress, absoluteAddressOf(stateElement, elementPathInfo, swapInfo.listIndexes[position]));
      notifyWrite(elementAddress, elementAbsAddress, receiver, handler, null, isCacheable(stateElement, elementAddress));
    }
  }
}

/**
 * `$listKeys` 宣言済みリストパスへの配列代入を「キー一致行のオブジェクト値展開」に
 * 変換する（docs/state-list-key-design.md §2）。
 *
 * 1. キー突合して、一致行は旧オブジェクトを据え置いたハイブリッド配列を作る
 * 2. ハイブリッド配列を通常の書き込み経路で格納する
 * 3. createListDiff で listIndex を確定し、変化フィールドだけを per-path 書き込みで発行
 *
 * 3 を格納後に行うのが要点。フィールド書き込みは `list.*.field` を親経由で解決する
 * ため、親（ハイブリッド配列）が既に格納されていなければ正しい行に届かない。
 * また per-path 書き込みは再び setByAddress に入るので、ネストしたリストパスが
 * 宣言されていればそのレベルのキー突合が再帰的に走る（§4）。
 *
 * 未宣言時のコストは stateElement.listKeys の null 判定 1 回のみ（§7-1）。
 */
function setKeyedListByAddress(
    target   : object,
    address  : IStateAddress,
    merge    : IKeyedListMerge,
    oldList  : readonly unknown[],
    receiver : any,
    handler  : IStateHandler
): any {
  const listPath = address.pathInfo.path;
  // diff の基準は「マージ相手にした配列」= 書き込み直前に格納されていた配列。
  // 読み手（applyChangeToFor / $getAll / resolve）は現在格納されている配列の
  // listIndex 台帳（listIndexesByList）へ収束するため、同じ基準で引くことで
  // 書き込みが dirty 化・キャッシュするアドレスと読み手のアドレスが一致する。
  // lastValue（最後に *適用* された配列）を基準にすると、for が未マウントで
  // lastValue が空のときに別台帳を作ってしまい、値は入っているのにワイルドカード
  // 読みだけ旧値のまま残る（設計書 §8.1）。
  // 格納より前に引くのは、格納時の walkDependency（listExpansion: "diff"）が
  // 先にハイブリッド配列の台帳を作ってしまうと、後から上書きした台帳との間で
  // 同じ分裂が起きるため。先に確定させておけば以降は全経路がこれに合流する。
  const listParentListIndex = address.listIndex;
  if (getListIndexesByList(oldList) === null) {
    // 一度も描画されていないリストは台帳自体が無い。先に生やしておかないと
    // isSameList 経路が空の oldIndexes をそのまま新台帳にしてしまう。
    createListDiff(listParentListIndex, null, oldList);
  }
  const diff = createListDiff(listParentListIndex, oldList, merge.list);
  const result = setByAddressCore(target, address, merge.list, receiver, handler, listPath);
  const elementPathInfo = getPathInfo(listPath + DELIMITER + WILDCARD);
  for (const match of merge.matched) {
    const fieldWrites = collectFieldWrites(match.oldRow, match.newRow);
    if (fieldWrites.length === 0) {
      continue;
    }
    // createListDiff の契約上 newIndexes の長さはハイブリッド配列と一致するため
    // 通常 undefined にはならない。仮に不変条件が破れても、per-path 書き込みを
    // 諦めるだけで値そのものは行オブジェクトへ反映する（skip すると state だけが
    // 旧値のまま残り、本機能が塞ごうとしている stale を作ってしまう）。
    const listIndex: IListIndex | undefined = diff.newIndexes[match.position];
    for (const write of fieldWrites) {
      if (typeof listIndex === "undefined") {
        match.oldRow[write.field] = write.value;
        continue;
      }
      const fieldPathInfo = getPathInfo(elementPathInfo.path + DELIMITER + write.field);
      const fieldAddress = createStateAddress(fieldPathInfo, listIndex);
      setByAddress(target, fieldAddress, write.value, receiver, handler);
    }
  }
  return result;
}

export function setByAddress(
    target   : object,
    address  : IStateAddress,
    value    : any,
    receiver : any,
    handler  : IStateHandler
): any {
  const listKeys = handler.stateElement.listKeys;
  if (listKeys != null && Array.isArray(value)) {
    const keySpec = listKeys.get(address.pathInfo.path);
    if (typeof keySpec !== "undefined") {
      const oldValue = getByAddress(target, address, receiver, handler);
      const merge = mergeKeyedList(address.pathInfo.path, keySpec, oldValue, value);
      if (merge !== null) {
        // merge が非 null なのは oldValue が非空配列のときだけ（mergeKeyedList 参照）
        return setKeyedListByAddress(target, address, merge, oldValue as readonly unknown[], receiver, handler);
      }
    }
  }
  return setByAddressCore(target, address, value, receiver, handler, null);
}

function setByAddressCore(
    target   : object,
    address  : IStateAddress,
    value    : any,
    receiver : any,
    handler  : IStateHandler,
    keyedMergePath: string | null
): any {
  const stateElement = handler.stateElement;
  const path = address.pathInfo.path;
  // 読み書き境界の hook（設計案 H1、書き側）。無ければ判定 1 回
  const hooks = stateElement.addressHooks;
  if (hooks) {
    const writeHooks = hooks.write;
    for (let i = 0; i < writeHooks.length; i++) {
      const handled = writeHooks[i](stateElement, address, value, receiver, handler);
      if (handled !== NOT_HANDLED) return handled;
    }
  }
  // D22 後段（接ぎ木済みボリュームの親の丸ごと書き禁止）は webComponent/addressHooks.ts の write hook が担う
  // 再帰 getter への書き込み禁止（[wcs/recursion-readonly]）は recursion/addressHooks.ts の write hook が担う
  // occurrence（wc-bindable の `semantics: "event"`）由来の書き込みは、同値でも
  // 「もう一度起きた」ことを落としてはならないため same-value guard を 1 回だけ飛ばす。
  // トークンはここで消費されるので、この write の内側で走る他の書き込みには波及しない。
  // 要素から来た書き込み（proxy/occurrenceWrite.ts）: 2 = occurrence。要素パスへ書いても入れ替えにしない
  const elementWrite = consumeElementWrite();
  const skipSameValueGuard = elementWrite > 1;

  // --- fast path: 宣言済み getter/setter でも swap 対象でもない、親を持つ葉パス ---
  // 従来は same-value guard の値読み・hasByAddress・実書き込みがそれぞれ親チェーンを
  // 解決していた（キャッシュヒットでも getByAddress 呼び出しの固定費 ×3）。
  // 親を 1 回だけ解決し、同じ親オブジェクトに対して guard 判定と Reflect.set を行う。
  // 非オブジェクト親などの例外形は従来経路へ倒し、挙動差を作らない。
  if (!(path in target) && address.parentAddress !== null && !stateElement.elementPaths.has(path)) {
    const parentValue = getByAddress(target, address.parentAddress, receiver, handler);
    if (typeof parentValue === "object" && parentValue !== null) {
      // ワイルドカード末尾で listIndex が無い不正アドレスは、従来どおり
      // 書き込み時（enqueue 済みの try 内）に raiseError する → key は undefined のまま持ち回す
      const lastSegment = address.pathInfo.lastSegment;
      const key: PropertyKey | undefined = lastSegment === WILDCARD
        ? address.listIndex?.index
        : lastSegment;
      let devOldValue: unknown;
      let devHasOldValue = false;
      if (!skipSameValueGuard && config.sameValueGuard && (value === null || typeof value !== "object")) {
        // hasByAddress と同じ「初期化済みスロットか」判定（undefined 格納と未初期化を区別）
        const has = key !== undefined && key in parentValue;
        const oldValue = key !== undefined ? (parentValue as Record<PropertyKey, unknown>)[key] : undefined;
        if (has && Object.is(oldValue, value)) {
          return true;
        }
        devOldValue = oldValue;
        devHasOldValue = true;
      }
      if (lastSegment === WILDCARD) {
        // 以降の通知・キャッシュ・prev の記録は、差し替えた後の行のアドレスで行う（#333）
        address = renewReplacedRow(stateElement, address, parentValue, key, value);
      }
      // key が undefined（listIndex の無い不正アドレス）なら読みは undefined — 書き込みが下で投げる
      // 購読者の収集は書き込みの**前**（旧値の鍵が要る）。そこからの依存ウォークは
      // 書き込みの**後**（下の finally の walkKeyedDependents）
      const keyedSubscribers = notifyKeyed(stateElement, path, devHasOldValue, devOldValue, value,
        () => (parentValue as Record<PropertyKey, unknown>)[key as PropertyKey]);
      const cacheable = isCacheable(stateElement, address);
      const absAddress = liftAddress(stateElement, address);
      if (devtoolsSink !== null) {
        devtoolsSink({
          type: "state:write",
          absoluteAddress: absAddress,
          value,
          oldValue: devOldValue,
          hasOldValue: devHasOldValue,
        });
      }
      recordDeclaredPrevValue(stateElement, path, absAddress, devOldValue, devHasOldValue);
      let dispatchedExport = false;
      try {
        if (key === undefined) {
          // fast path 版の同じ取り違え（末尾ワイルドカードに listIndex が無い）。
          // 通常経路と同じ語彙で「何段必要か」を言う（pathDiagnostics.ts）。
          raiseError(wildcardScopeMessage(
            `path "${path}"`,
            address.pathInfo.wildcardCount,
            address.listIndex?.length ?? 0,
          ));
        }
        // 「親にそのキーが無い」書き込みは writeMissing hook（公開 getter への書き込み — X9）に先に聞く。
        // hook の無い state は判定 1 個で抜ける。hook が throw しても（setter の無い公開 getter）
        // 代入値をキャッシュに固定しないよう、呼ぶ前に印を立て、素通しなら戻す
        if (hooks && hooks.writeMissing.length !== 0 && lastSegment !== WILDCARD && !(key in parentValue)) {
          const missing = hooks.writeMissing;
          for (let i = 0; i < missing.length; i++) {
            dispatchedExport = true;
            const handled = missing[i](stateElement, address, parentValue, key, value, receiver, handler);
            if (handled !== NOT_HANDLED) {
              return handled;
            }
            dispatchedExport = false;
          }
        }
        if (lastSegment !== WILDCARD && address.listIndex !== null) {
          // 行の下のパス（外側の行の内側のリスト）が別の値に替わる。前の配列の行がこの行を親に持っていても、この行は
          // もうその配列を持たない — 台帳の付け替えの元にする（list/listIndexesByList.ts・#394）
          const previous = (parentValue as Record<PropertyKey, unknown>)[key];
          if (previous !== value) {
            if (releaseListAtParent(previous, address.listIndex, parentValue as Record<string, unknown>, lastSegment) && Array.isArray(value)) {
              keepPreviousList(value, previous);
            }
            holdListAtParent(value, address.listIndex);
          }
        }
        return Reflect.set(parentValue, key, value);
      } finally {
        notifyWrite(address, absAddress, receiver, handler, keyedMergePath, cacheable);
        walkKeyedDependents(keyedSubscribers, receiver, handler);
        if (dispatchedExport) {
          // Exported row paths are cacheable but absent from getterPaths. The
          // accessor may normalize or reject the input; never pin that input.
          dirtyCacheEntryByAbsoluteStateAddress(absAddress);
        } else {
          commitWriteCache(stateElement, path, absAddress, value, cacheable);
        }
        notifyWritten(stateElement, address.pathInfo, { value });
      }
    }
  }
  // --- end fast path ---

  // --- same-value guard (config.sameValueGuard・既定 ON) ---
  // primitive 値かつ Object.is 同値なら、set / enqueue / walkDependency / DOM 適用 /
  // $updatedCallback / DCC イベントを丸ごとスキップ（標準的なリアクティブ no-op）。
  // 参照型(object/array)は in-place mutation 取りこぼし防止のため素通し（ガードしない）。
  // devtools write イベント用: guard が既に取得した旧値のみ流用する
  // （参照型のために追加の get はしない — protocol §4.2）
  let devOldValue: unknown;
  let devHasOldValue = false;
  if (!skipSameValueGuard && config.sameValueGuard && (value === null || typeof value !== "object")) {
    const oldValue = getByAddress(target, address, receiver, handler);
    if (hasByAddress(target, address, receiver, handler) && Object.is(oldValue, value)) {
      return true;
    }
    devOldValue = oldValue;
    devHasOldValue = true;
  }
  // 購読者の収集は書き込みの**前**（旧値の鍵が要る）。ウォークは下の finally
  const keyedSubscribers = notifyKeyed(stateElement, path, devHasOldValue, devOldValue, value, () => getByAddress(target, address, receiver, handler));
  // --- end same-value guard ---
  const isSwappable = stateElement.elementPaths.has(address.pathInfo.path);
  const cacheable = isCacheable(stateElement, address);
  const absAddress = liftAddress(stateElement, address);
  if (devtoolsSink !== null) {
    devtoolsSink({
      type: "state:write",
      absoluteAddress: absAddress,
      value,
      oldValue: devOldValue,
      hasOldValue: devHasOldValue,
    });
  }
  recordDeclaredPrevValue(stateElement, path, absAddress, devOldValue, devHasOldValue);
  try {
    if (isSwappable) {
      return _setByAddressWithSwap(target, address, absAddress, value, receiver, handler, keyedMergePath, cacheable, elementWrite);
    } else {
      return _setByAddress(target, address, absAddress, value, receiver, handler, keyedMergePath, cacheable);
    }
  } finally {
    // 鍵付き購読の派生先（`notifyWrite` は `_setByAddress` の中で済んでいる）。書き込み後なので
    // リスト展開が新しい値を読む
    walkKeyedDependents(keyedSubscribers, receiver, handler);
    // 要素書き込み（#4）の代入値は、書き込んだアドレスのキャッシュに固定しない。入れ替えでは listIndex が
    // 値に付いて動くので、書き込んだ時点の listIndex がこの位置に残るとは限らない — 固定すると、台帳は
    // 入れ替わったのにキャッシュだけが位置のまま交差する。notifyWrite が無効化した項目を、次の読みが
    // 台帳に沿って読み直す
    if (!isSwappable) {
      commitWriteCache(stateElement, path, absAddress, value, cacheable);
    }
    notifyWritten(stateElement, address.pathInfo, { value });
  }
}

